        art("nk-122", "nk1", 122, "122", "Неуплата или неполная уплата налога",
            "1. Неуплата или неполная уплата сумм налога (сбора, страховых взносов) в результате занижения налоговой базы, иного неправильного исчисления налога или других неправомерных действий (бездействия) влечёт взыскание штрафа в размере 20 процентов от неуплаченной суммы налога (сбора, страховых взносов).")

        // UPK
        doc("upk", "Уголовно-процессуальный кодекс Российской Федерации", "code", "УПК РФ")
